mapper.update:
UPDATE solution_comment
SET like_count=like_count+#{delta},updated_at=#{updatedAt}
WHERE comment_id=#{commentId} AND like_count+#{delta} >= 0

mapper.select:
SELECT comment_id,solution_id,user_id,root_id,parent_id,reply_to_user_id,content,state,deleted_by,deleted_at,
       like_count,reply_count,client_request_id,created_at,updated_at
FROM solution_comment
WHERE root_id=#{rootId}
ORDER BY created_at ASC, comment_id ASC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE solution_comment
SET state=#{newState},deleted_by=#{operatorId},deleted_at=#{now},updated_at=#{now}
WHERE comment_id=#{commentId} AND solution_id=#{solutionId} AND state='VISIBLE'

mapper.select:
SELECT COUNT(*) FROM solution_comment
WHERE 1=1
AND solution_id=#{solutionId}
AND state=#{state}

SELECT comment_id,solution_id,user_id,root_id,parent_id,reply_to_user_id,content,state,deleted_by,deleted_at,
       like_count,reply_count,client_request_id,created_at,updated_at
FROM solution_comment
WHERE 1=1
AND solution_id=#{solutionId}
AND state=#{state}
ORDER BY created_at DESC,comment_id DESC
LIMIT #{offset},#{limit}
